import { copyFile, mkdir, readFile, readdir, writeFile } from 'node:fs/promises';
import { join } from 'node:path';

// Use the installed license texts, including each package's copyright notices.
// Fail the build if an updated dependency is missing its license file.
export async function generateLicenses() {
  const lock = JSON.parse(await readFile('package-lock.json', 'utf8'));
  const sections = [
    'YourDialogue — Third-party notices',
    'Generated by scripts/licenses.mjs from package-lock.json and installed packages.\n' +
      'Third-party components retain their own licenses.\n' +
      'Electron and Chromium notices are also included in the distribution licenses/ directory.\n' +
      'This file covers runtime npm dependencies, including transitive dependencies.',
  ];
  const dependencies = Object.entries(lock.packages)
    .filter(([path, pkg]) => path && !pkg.dev)
    .sort(([a], [b]) => a.localeCompare(b, 'en'));
  dependencies.push(['node_modules/electron', lock.packages['node_modules/electron']]);
  for (const [path, pkg] of dependencies) {
    const metadata = JSON.parse(await readFile(join(path, 'package.json'), 'utf8'));
    const files = (await readdir(path))
      .filter((name) => /^(licen[sc]e|copying|notice)(?:[.\-_]|$)/i.test(name))
      .sort();
    if (!files.some((name) => /^(licen[sc]e|copying)(?:[.\-_]|$)/i.test(name))) {
      throw new Error(`Missing license text: ${path}`);
    }
    const texts = await Promise.all(
      files.map(async (name) => `${name}\n${(await readFile(join(path, name), 'utf8')).trim()}`),
    );
    sections.push(
      `${metadata.name}@${pkg.version}\nLicense: ${pkg.license}\n\n${texts.join('\n\n')}`,
    );
  }
  const output = sections.join('\n\n' + '='.repeat(72) + '\n\n') + '\n';
  await writeFile('THIRD_PARTY_NOTICES.txt', output);
  await mkdir('dist/licenses', { recursive: true });
  await copyFile('node_modules/electron/dist/LICENSE', 'dist/licenses/Electron-LICENSE.txt');
  await copyFile(
    'node_modules/electron/dist/LICENSES.chromium.html',
    'dist/licenses/LICENSES.chromium.html',
  );
}
